#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int H, W, D;
    if (scanf("%d %d %d", &H, &W, &D) != 3) return 0;

    int N = H * W;

    int *row = (int *)malloc((N + 1) * sizeof(int));
    int *col = (int *)malloc((N + 1) * sizeof(int));
    long long *pref = (long long *)calloc(N + 1, sizeof(long long));

    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            int x;
            scanf("%d", &x);
            row[x] = i;
            col[x] = j;
        }
    }

    for (int x = D + 1; x <= N; x++) {
        long long dist = llabs((long long)row[x] - row[x - D]) + llabs((long long)col[x] - col[x - D]);
        pref[x] = pref[x - D] + dist;
    }

    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int L, R;
        scanf("%d %d", &L, &R);
        printf("%lld\n", pref[R] - pref[L]);
    }

    free(row);
    free(col);
    free(pref);
    return 0;
}

