int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, D;
    cin >> H >> W >> D;

    int N = H * W;
    vector<pair<int,int>> pos(N + 1);

    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) {
            int a;
            cin >> a;
            pos[a] = {i, j};
        }
    }

    vector<long long> cost(N + 1, 0);

    for (int x = D + 1; x <= N; ++x) {
        auto [r1, c1] = pos[x];
        auto [r0, c0] = pos[x - D];
        cost[x] = cost[x - D] + abs(r1 - r0) + abs(c1 - c0);
    }

    int Q;
    cin >> Q;
    while (Q--) {
        int L, R;
        cin >> L >> R;
        cout << cost[R] - cost[L] << '\n';
    }

    return 0;
}

