import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int H = fs.nextInt();
        int W = fs.nextInt();
        int D = fs.nextInt();

        int N = H * W;
        int[] row = new int[N + 1];
        int[] col = new int[N + 1];

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                int x = fs.nextInt();
                row[x] = i;
                col[x] = j;
            }
        }

        long[] cost = new long[N + 1];
        for (int x = D + 1; x <= N; x++) {
            cost[x] = cost[x - D] + Math.abs(row[x] - row[x - D]) + Math.abs(col[x] - col[x - D]);
        }

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            int L = fs.nextInt();
            int R = fs.nextInt();
            sb.append(cost[R] - cost[L]).append('\n');
        }

        System.out.print(sb.toString());
    }
}
